import {esc,icon} from './ui.mjs';
import {validateFormulaCode} from './research-delivery-model.mjs';
import {createDocumentServiceClient,watchDocumentService,fileBase64,documentServiceLoginHref} from './document-services-client.mjs';
const IMAGE_BYTES=2*1024*1024,IMAGE_DIMENSION=1000;
export function formulaImageDimensions(width,height,max=IMAGE_DIMENSION){if(!Number.isFinite(width)||!Number.isFinite(height)||width<1||height<1)throw Error('无法读取图片尺寸，请更换图片。');const scale=Math.min(1,max/Math.max(width,height));return {width:Math.max(1,Math.round(width*scale)),height:Math.max(1,Math.round(height*scale))};}
export async function prepareFormulaImage(file,{maxFileBytes=IMAGE_BYTES,maxDimension=IMAGE_DIMENSION,documentImpl=document}={}){if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('请选择 PNG、JPG 或 WebP 格式的公式截图。');if(!file.size||file.size>10*1024*1024)throw Error('原始图片最大 10MB，请裁剪到单条清晰公式后重试。');const win=documentImpl.defaultView,source='data:'+file.type+';base64,'+await fileBase64(file),image=new win.Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('图片读取失败，请更换有效截图。'));image.src=source;});const dimensions=formulaImageDimensions(image.naturalWidth,image.naturalHeight,Math.min(maxDimension,IMAGE_DIMENSION));let output=source;if(dimensions.width!==image.naturalWidth||dimensions.height!==image.naturalHeight||file.size>Math.min(maxFileBytes,IMAGE_BYTES)){const canvas=documentImpl.createElement('canvas');canvas.width=dimensions.width;canvas.height=dimensions.height;const context=canvas.getContext('2d');if(!context)throw Error('当前浏览器无法处理截图，请先缩小图片后重试。');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);output=canvas.toDataURL('image/png');}const match=/^data:(image\/(?:png|jpeg|webp));base64,([A-Za-z0-9+/=]+)$/.exec(output);if(!match||Math.floor(match[2].length*3/4)>Math.min(maxFileBytes,IMAGE_BYTES))throw Error('处理后的截图仍超过 2MB，请裁剪后重新选择。');return {mime:match[1],imageBase64:match[2],preview:output,...dimensions};}
export function mountFormulaOcr({container,onApply,notify=()=>{},fetchImpl,prepareImage=prepareFormulaImage,uuid=()=>crypto.randomUUID(),pollInterval=1500}={}){
 let alive=true,session=null,cap={},image=null,latex='',busy=false,unwatch=()=>{},timer=null,sequence=0,requestKey=uuid();const current=()=>alive&&container.isConnected,$=s=>container.querySelector(s),client=createDocumentServiceClient({fetchImpl,isCurrent:current});const dispose=()=>{if(!alive)return;alive=false;sequence++;clearTimeout(timer);client.dispose();unwatch();};unwatch=watchDocumentService(container,dispose);
 const status=(message,error=false)=>{const node=$('[data-formula-ocr-status]');if(node){node.textContent=message;node.classList.toggle('is-error',error);}};
 const setBusy=value=>{busy=value;container.setAttribute('aria-busy',String(value));container.querySelectorAll('input,button,textarea').forEach(node=>node.disabled=value);if(!value){const button=$('[data-formula-ocr-submit]');if(button)button.disabled=!image;const apply=$('[data-formula-ocr-apply]');if(apply)apply.disabled=!latex.trim();}};
 function render(){container.innerHTML=`<section class="document-service formula-ocr"><div class="document-service-intro"><span class="document-service-icon">${icon('file',22)}</span><div><h3>把公式截图，转成可编辑公式</h3><p>适用于清晰的印刷数学公式 · PNG / JPG / WebP</p></div></div><label class="document-service-upload">${icon('upload',23)}<b>选择一张公式截图</b><span>建议裁剪单条公式；提交前自动缩小至 ${Math.min(Number(cap.maxDimension)||IMAGE_DIMENSION,IMAGE_DIMENSION)}px，最大 2MB</span><input type="file" data-formula-ocr-file accept="image/png,image/jpeg,image/webp" aria-label="选择公式截图"></label><div class="formula-ocr-image" data-formula-ocr-preview hidden></div><label class="document-service-consent"><input type="checkbox" data-formula-ocr-consent><span>我有权处理此截图，并同意提交阿里云公式识别服务；识别结果需核对后再使用。</span></label><div class="document-service-actions"><button type="button" class="btn primary" data-formula-ocr-submit disabled>${icon('spark',16)} 识别公式</button><span>当前试用免费，不扣科研积分；每账户每日最多 ${Number(cap.userDailyLimit)||20} 次。</span></div><p class="document-service-status" data-formula-ocr-status role="status" aria-live="polite">识别后可先修改 LaTeX，再应用到下方公式编辑器。</p><div class="formula-ocr-output" data-formula-ocr-output hidden><label class="document-service-field">识别结果（可修改）<textarea data-formula-ocr-latex maxlength="2000" rows="4" aria-label="修改识别的公式"></textarea></label><div class="formula-ocr-render" data-formula-ocr-render aria-label="识别公式排版预览"></div><div class="document-service-actions"><button type="button" class="btn primary" data-formula-ocr-apply>应用到公式编辑器</button><span>应用会替换编辑器中的当前公式；原有内容保留在编辑历史。</span></div></div></section>`;$('[data-formula-ocr-file]').onchange=()=>void selectImage();$('[data-formula-ocr-submit]').onclick=()=>void recognize();$('[data-formula-ocr-latex]').oninput=()=>{latex=$('[data-formula-ocr-latex]').value;$('[data-formula-ocr-apply]').disabled=!latex.trim();void previewLatex();};$('[data-formula-ocr-apply]').onclick=async()=>{if(busy)return;const snapshot=latex;try{const value=validateFormulaCode(snapshot),{renderFormulaSvg}=await import('./assets/research-formula.js');renderFormulaSvg(value);if(!current()||latex!==snapshot)return;onApply?.(value);status('公式已填入下方编辑器，请核对符号、上下标及适用条件。');notify('识别公式已应用，修改后可保存与导出。');}catch(error){if(current()&&latex===snapshot)status('公式尚未应用：'+error.message,true);}};}
 async function selectImage(){const ticket=++sequence;clearTimeout(timer);image=null;latex='';$('[data-formula-ocr-output]').hidden=true;$('[data-formula-ocr-preview]').hidden=true;const file=$('[data-formula-ocr-file]').files?.[0];if(!file){setBusy(false);return;}setBusy(true);status('正在本地整理截图，尚未上传…');try{const prepared=await prepareImage(file,{maxFileBytes:cap.maxFileBytes,maxDimension:cap.maxDimension,documentImpl:container.ownerDocument});if(!current()||ticket!==sequence)return;image=prepared;requestKey=uuid();const preview=$('[data-formula-ocr-preview]');preview.replaceChildren();const img=container.ownerDocument.createElement('img');img.src=prepared.preview;img.alt='待识别的公式截图';preview.append(img);preview.hidden=false;status(`截图已准备好 · ${prepared.width} × ${prepared.height}px。确认云端处理后开始识别。`);}catch(error){if(current()&&ticket===sequence)status(error.message,true);}finally{if(current()&&ticket===sequence)setBusy(false);}}
 async function previewLatex(){const ticket=++sequence,target=$('[data-formula-ocr-render]');try{const checked=validateFormulaCode(latex),{renderFormulaSvg}=await import('./assets/research-formula.js');if(!current()||ticket!==sequence)return;target.innerHTML=renderFormulaSvg(checked);}catch(error){if(current()&&ticket===sequence)target.textContent=error.message||'请核对 LaTeX 语法。';}}
 async function finish(value){if(!current())return;if(value.status==='running'){status('正在识别，请稍候；不会重复提交。');timer=setTimeout(()=>void poll(value.id),pollInterval);return;}if(value.status!=='completed'||typeof value.latex!=='string')throw Error(typeof value.error==='string'?value.error:'未能识别到有效公式，请裁剪更清晰的印刷公式截图后重试。');latex=validateFormulaCode(value.latex);$('[data-formula-ocr-latex]').value=latex;$('[data-formula-ocr-output]').hidden=false;setBusy(false);status('识别完成。请核对或修改结果，点击“应用”后才会替换当前公式。');void previewLatex();}
 async function poll(id){try{await finish(await client.request('/formula-recognitions/'+encodeURIComponent(id)));}catch(error){if(current()&&error.name!=='AbortError'){setBusy(false);status(error.message,true);}}}
 async function recognize(){if(busy||!image)return;if(!$('[data-formula-ocr-consent]').checked)return status('请先确认截图处理授权与云端识别说明。',true);setBusy(true);status('正在识别公式…');try{const latest=await client.request('/auth/me');if(latest.user?.id!==session.user.id)throw Error('登录账户已变化，请关闭识别区后重新打开。');await finish(await client.request('/formula-recognitions',{imageBase64:image.imageBase64,mime:image.mime,consent:true,expectedUserId:session.user.id,idempotencyKey:requestKey},{timeout:60000}));}catch(error){if(current()&&error.name!=='AbortError'){setBusy(false);status(error.message,true);}}}
 const ready=(async()=>{container.innerHTML='<p class="document-service-loading" role="status">正在读取公式识别服务…</p>';try{const [me,capabilities]=await Promise.all([client.request('/auth/me'),client.request('/capabilities')]);session=me;cap=capabilities.formulaOcr||{};if(!me.user?.id){container.innerHTML=`<div class="document-service-empty"><h3>登录后识别公式截图</h3><p>手动编辑、排版和导出仍可继续使用。</p><a class="btn primary" href="${esc(documentServiceLoginHref())}">登录账户 →</a></div>`;return;}if(!cap.ready){container.innerHTML='<div class="document-service-empty"><h3>公式图片识别暂未开放</h3><p>请稍后再试。你仍可手动输入 LaTeX、使用公式模板并导出。</p></div>';return;}render();}catch(error){if(current()&&error.name!=='AbortError')container.innerHTML=`<div class="document-service-empty"><p role="alert">${esc(error.status===401?'请登录后再使用公式图片识别。':error.message)}</p>${error.status===401?`<a class="btn primary" href="${esc(documentServiceLoginHref())}">登录账户 →</a>`:''}</div>`;}})();return {ready,dispose};
}
